//! K3c-3 — the boolean differential: OCCT's own volumes and boundary
//! areas for the oblique plane cuts, against our exact composition
//! and closed-form measure.
//!
//! The corpus (`tests/fixtures/k3c_booleans.json`) was generated by
//! `scripts/parity/regen_k3c_booleans.py` through the same pinned
//! FreeCAD 1.0.0 AppImage (r39109) the parity gate uses: for every
//! canonical case, OCCT's `cut` / `common` of the primitive with a
//! generous box proxying the `+n` halfspace — a box with one face ON
//! the cutting plane, an order of magnitude larger than the operand —
//! with the results' `Volume()` and `Area()` recorded.
//!
//! The differential is bidirectional here (both engines compute the
//! whole result, not a superset): every OCCT volume and area must
//! agree with our composed solid's `brep_volume` / `brep_area` within
//! the tolerance OCCT's own quadrature admits. OCCT's `Volume()` on
//! analytic B-reps is adaptive quadrature, not closed form — the
//! corpus regeneration observed the agreement scale and the pin below
//! matches it with an order of magnitude of headroom. If our closed
//! forms were wrong by even a hair, OCCT's own numbers would disagree.

use fc_base::Vector3;
use fc_part::brep_boolean::{cone_plane_boolean, cylinder_plane_boolean, BooleanOp};
use fc_part::measure::{brep_area, brep_volume};

fn v3(x: f64, y: f64, z: f64) -> Vector3 {
    Vector3::new(x, y, z)
}

fn vec_from_json(v: &serde_json::Value) -> Vector3 {
    let a = v.as_array().expect("vector as [x, y, z]");
    v3(
        a[0].as_f64().expect("x"),
        a[1].as_f64().expect("y"),
        a[2].as_f64().expect("z"),
    )
}

fn approx(a: f64, b: f64, what: &str) {
    // OCCT's adaptive quadrature on these analytic solids agreed with
    // the closed forms to 4.4e-9 relative (volume) / 2.8e-9 (area) at
    // regeneration time; the pin keeps an order of magnitude of
    // headroom. The perpendicular sections came out bit-exact.
    let scale = a.abs().max(b.abs()).max(1e-12);
    assert!(
        (a - b).abs() <= 1e-8 * scale,
        "{what}: {a} vs {b} (diff {})",
        (a - b).abs()
    );
}

#[test]
fn occt_boolean_volumes_and_areas_agree_with_the_exact_composition() {
    let text = include_str!("fixtures/k3c_booleans.json");
    let corpus: serde_json::Value = serde_json::from_str(text).expect("the corpus parses");
    let cases = corpus["cases"].as_array().expect("the case list");
    assert!(!cases.is_empty(), "the corpus carries cases");

    for case in cases {
        let name = case["name"].as_str().expect("the case name");
        let plane_point = vec_from_json(&case["plane_point"]);
        let plane_normal = vec_from_json(&case["plane_normal"]);
        let prim = &case["primitive"];
        let kind = prim["kind"].as_str().expect("the primitive kind");

        for result in case["results"].as_array().expect("the results") {
            let op_name = result["op"].as_str().expect("cut or common");
            let op = if op_name == "cut" {
                BooleanOp::Cut
            } else {
                BooleanOp::Common
            };
            let outcome = match kind {
                "Cylinder" => cylinder_plane_boolean(
                    op,
                    vec_from_json(&prim["origin"]),
                    vec_from_json(&prim["axis"]),
                    prim["radius"].as_f64().expect("radius"),
                    prim["height"].as_f64().expect("height"),
                    plane_point,
                    plane_normal,
                ),
                "Cone" => cone_plane_boolean(
                    op,
                    vec_from_json(&prim["origin"]),
                    vec_from_json(&prim["axis"]),
                    prim["base_radius"].as_f64().expect("base_radius"),
                    prim["top_radius"].as_f64().expect("top_radius"),
                    prim["height"].as_f64().expect("height"),
                    plane_point,
                    plane_normal,
                ),
                other => panic!("unknown primitive kind {other}"),
            }
            .unwrap_or_else(|e| panic!("{name}/{op_name}: the boolean composes: {e}"));

            if result["empty"].as_bool().unwrap_or(false) {
                assert!(
                    matches!(
                        outcome.kind,
                        fc_part::brep_boolean::BooleanOutcomeKind::Empty
                    ),
                    "{name}/{op_name}: OCCT empty, ours {outcome:?}"
                );
                continue;
            }
            let brep = match &outcome.kind {
                fc_part::brep_boolean::BooleanOutcomeKind::Solid(b) => b,
                other => panic!("{name}/{op_name}: OCCT solid, ours {other:?}"),
            };
            let occt_volume = result["volume"].as_f64().expect("OCCT volume");
            let occt_area = result["area"].as_f64().expect("OCCT area");
            approx(
                brep_volume(brep).unwrap(),
                occt_volume,
                "{name}/{op_name} volume: ours vs OCCT",
            );
            approx(
                brep_area(brep).unwrap(),
                occt_area,
                "{name}/{op_name} area: ours vs OCCT",
            );
        }
    }
}
